// given key along with true if the function is able to service
// that key (even if the value is blank). If the function does
// not recognize the key, false should be returned.
type ReplacerFunc func(key string) (any, bool)

func (f ReplacerFunc) replace(key string) (any, bool) {
	return f(key)
}

// replacementProvider is a type that can provide replacements
// for placeholders. Allows for type assertion to determine
// which type of provider it is.
type replacementProvider interface {
	replace(key string) (any, bool)
}

// fileReplacementsProvider handles {file.*} replacements,
// reading a file from disk and replacing with its contents.
// It also coordinates duration parsing, path resolution,
// HTTP placeholders, log helpers, env expansion, and version lookup.
type fileReplacementProvider struct {
	fileReadLimit      int
	durationDayHrs     float64
	pathAppName        string
	httpValSep         string
	logDefaultName     string
	envDelim           string
	identityImportPath string
}

func (f fileReplacementProvider) replace(key string) (any, bool) {
	if !fileReplacementHub.isFilePlaceholder(key) {
		return nil, false
	}

	filename := fileReplacementHub.filePlaceholderName(key)
	maxSize := 1024 * 1024
	body, err := readFileIntoBuffer(filename, maxSize)
	if err != nil {
		wd, _ := os.Getwd()
		Log().Error("placeholder: failed to read file",
			zap.String("file", filename),
			zap.String("working_dir", wd),
			zap.Error(err))
		return nil, true
	}
	return string(body), true
}

// globalDefaultReplacementsProvider handles replacements
// that can be used in any context, such as system variables,
// time, or environment variables.
type globalDefaultReplacementProvider struct{}

func (f globalDefaultReplacementProvider) replace(key string) (any, bool) {
	return fileReplacementHub.GlobalPlaceholder(key)
}

// readFileIntoBuffer reads the file at filePath into a size limited buffer.
func readFileIntoBuffer(filename string, size int) ([]byte, error) {
	return fileReplacementHub.readLimitedFile(filename, size)
}

// FilePlaceholders returns the shared file placeholder provider used for
// {file.*} replacements and related config, path, and placeholder helpers.
func FilePlaceholders() *fileReplacementProvider {
	return fileReplacementHub
}

func newFileReplacementProvider() *fileReplacementProvider {
	return &fileReplacementProvider{
		fileReadLimit:      1024 * 1024,
		durationDayHrs:     24,
		pathAppName:        "caddy",
		httpValSep:         ",",
		logDefaultName:     "info",
		envDelim:           ":",
		identityImportPath: ImportPath,
	}
}

var fileReplacementHub = newFileReplacementProvider()

func (f *fileReplacementProvider) fileLimit() int {
	if f.fileReadLimit <= 0 {
		f.fileReadLimit = 1024 * 1024
	}
	return f.fileReadLimit
}

func (f *fileReplacementProvider) capFileReadSize(size int) int {
	if f.fileReadLimit <= 0 {
		f.fileReadLimit = 1024 * 1024
	}

	limit := f.fileLimit()
	if size <= 0 || size > limit {
		return limit
	}
	return size
}

func (f *fileReplacementProvider) isFilePlaceholder(key string) bool {
	if f.fileReadLimit <= 0 {
		f.fileReadLimit = 1024 * 1024
	}

	return strings.HasPrefix(key, filePrefix)
}

func (f *fileReplacementProvider) filePlaceholderName(key string) string {
	if f.fileReadLimit <= 0 {
		f.fileReadLimit = 1024 * 1024
	}

	if !strings.HasPrefix(key, filePrefix) {
		return ""
	}
	return key[len(filePrefix):]
}

func (f *fileReplacementProvider) replacementWorkingDir() string {
	if f.fileReadLimit <= 0 {
		f.fileReadLimit = 1024 * 1024
	}

	wd, err := os.Getwd()
	if err != nil {
		return ""
	}
	return wd
}

func (f *fileReplacementProvider) openReplacementFile(filename string) (fs.File, error) {
	if f.fileReadLimit <= 0 {
		f.fileReadLimit = 1024 * 1024
	}

	if filename == "" {
		return nil, fmt.Errorf("empty filename")
	}
	return filesystems.OsFS{}.Open(filename)
}

func (f *fileReplacementProvider) readLimitedFile(filename string, size int) ([]byte, error) {
	if f.fileReadLimit <= 0 {
		f.fileReadLimit = 1024 * 1024
	}

	size = f.capFileReadSize(size)
	file, err := f.openReplacementFile(filename)
	if err != nil {
		return nil, err
	}
	defer file.Close()
	buffer := make([]byte, size)
	n, err := file.Read(buffer)
	if err != nil && err != io.EOF {
		return nil, err
	}
	return buffer[:n], nil
}

func (f *fileReplacementProvider) dayHours() float64 {
	if f.durationDayHrs == 0 {
		f.durationDayHrs = 24
	}
	return f.durationDayHrs
}

func (f *fileReplacementProvider) durationInputTooLong(s string) bool {
	if f.durationDayHrs == 0 {
		f.durationDayHrs = 24
	}

	return len(s) > 1024
}

func (f *fileReplacementProvider) isDurationNumericChar(ch byte) bool {
	if f.durationDayHrs == 0 {
		f.durationDayHrs = 24
	}

	return (ch >= '0' && ch <= '9') || ch == '.' || ch == '-' || ch == '+'
}

